  "implementation": "def solve(case):
    nodes = case['nodes']
    core_dist = case['core_distance']
    distances = case['distances']

    # Build edges with mutual reachability weights
    edges = []
    for u, v, d in distances:
        weight = max(core_dist[u], core_dist[v], d)
        edges.append((weight, u, v))

    # Sort deterministically: by weight, then by u, then by v
    edges.sort(key=lambda x: (x[0], x[1], x[2]))

    # Union-Find (Disjoint Set) data structure
    parent = {node: node for node in nodes}
    rank = {node: 0 for node in nodes}

    def find(x):
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x

    def union(x, y):
        xr, yr = find(x), find(y)
        if xr == yr:
            return False
        if rank[xr] < rank[yr]:
            parent[xr] = yr
        elif rank[xr] > rank[yr]:
            parent[yr] = xr
        else:
            parent[yr] = xr
            rank[xr] += 1
        return True

    mst_edges = []
    total_weight = 0.0

    for weight, u, v in edges:
        if union(u, v):
            mst_edges.append([u, v, weight])
            total_weight += weight

    return {
        'mst_edges': mst_edges,
        'total_weight': total_weight
    }
